// Core tests: the 18 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. Every hand-derived expected value below was computed by hand
// from the SPEC's rules (integer cents + the R(q, d) half-up rule);
// the derivations are listed in AUTHOR-CHECK.md section 2 and were
// independently rechecked with exact rational arithmetic.

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatFixedScaled,
  formatMoney,
  run,
} from "../public/js/core/breakeven.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = { fixedCost: "120000", price: "400", variableCost: "150", expectedUnits: "" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

function moneyToCents(text) {
  const dot = text.indexOf(".");
  const whole = dot === -1 ? text : text.slice(0, dot);
  const fraction = dot === -1 ? "" : text.slice(dot + 1);
  return BigInt(whole) * 100n + BigInt(fraction.padEnd(2, "0") || "0");
}

test("worked anchors: zero fixed cost is 0/0; zero variable cost is a 100% ratio", () => {
  const zeroFixed = run({ fixedCost: "0", price: "250", variableCost: "100", expectedUnits: "" });
  assert.equal(zeroFixed.ok, true);
  assert.equal(zeroFixed.result.breakevenUnits, 0);
  assert.equal(zeroFixed.result.breakevenRevenue, "0.00");
  const zeroVariable = run({ fixedCost: "50000", price: "100", variableCost: "0", expectedUnits: "" });
  assert.equal(zeroVariable.ok, true);
  assert.equal(zeroVariable.result.contributionMarginRatioPercent, "100.00");
});

test("boundary: amount limits 999999999.99 and 0.01; just over the max is RANGE", () => {
  const max = run({
    fixedCost: "999999999.99",
    price: "999999999.99",
    variableCost: "999999999.98",
    expectedUnits: "",
  });
  assert.equal(max.ok, true);
  assert.equal(max.result.contributionMarginPerUnit, "0.01");
  assert.equal(max.result.breakevenUnits, 99999999999);
  const minPrice = run({ fixedCost: "100", price: "0.01", variableCost: "0", expectedUnits: "" });
  assert.equal(minPrice.ok, true);
  assert.equal(minPrice.result.breakevenUnits, 10000);
  assert.deepEqual(errorOf({ ...base, fixedCost: "1000000000" }), {
    code: "RANGE",
    field: "fixedCost",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, price: "9999999999.99" }), {
    code: "INPUT_LIMIT",
    field: "price",
    row: null,
  });
});

test("boundary: expected units 100000000 succeeds, 100000001 is RANGE, 10 digits is INPUT_LIMIT", () => {
  const max = run({ ...base, expectedUnits: "100000000" });
  assert.equal(max.ok, true);
  assert.equal(max.result.marginOfSafety.expectedUnits, 100000000);
  assert.deepEqual(errorOf({ ...base, expectedUnits: "100000001" }), {
    code: "RANGE",
    field: "expectedUnits",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, expectedUnits: "1000000000" }), {
    code: "INPUT_LIMIT",
    field: "expectedUnits",
    row: null,
  });
});

test("boundary: raw length exactly 12 is accepted, 13 is INPUT_LIMIT before grammar", () => {
  const exact = run({ ...base, fixedCost: "999999999.99" });
  assert.equal(exact.ok, true);
  assert.deepEqual(errorOf({ ...base, fixedCost: "9999999999.99" }), {
    code: "INPUT_LIMIT",
    field: "fixedCost",
    row: null,
  });
  // A 13-unit value that would also fail the grammar still reports INPUT_LIMIT.
  assert.deepEqual(errorOf({ ...base, fixedCost: "1000000000.00" }), {
    code: "INPUT_LIMIT",
    field: "fixedCost",
    row: null,
  });
});

test("money grammar: signs, exponents, commas, trailing dots, leading dots and non-ASCII digits are DECIMAL_FORMAT; leading zeros are too", () => {
  for (const bad of ["-100", "+100", "1e3", "2,400", "100.", ".5", "１２３", "100 ", "00.50", "007"]) {
    assert.deepEqual(errorOf({ ...base, fixedCost: bad }), {
      code: "DECIMAL_FORMAT",
      field: "fixedCost",
      row: null,
    });
  }
  const loneZero = run({ ...base, fixedCost: "0.50" });
  assert.equal(loneZero.ok, true);
  const zeroCents = run({ ...base, fixedCost: "0.00" });
  assert.equal(zeroCents.ok, true);
  assert.equal(zeroCents.result.breakevenUnits, 0);
});

test("an active field reports UNICODE before EMPTY and grammar; EMPTY names the first blank required field", () => {
  assert.deepEqual(errorOf({ ...base, fixedCost: "\uD800" }), {
    code: "UNICODE",
    field: "fixedCost",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, expectedUnits: "\uD800" }), {
    code: "UNICODE",
    field: "expectedUnits",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, fixedCost: "" }), {
    code: "EMPTY",
    field: "fixedCost",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, variableCost: "" }), {
    code: "EMPTY",
    field: "variableCost",
    row: null,
  });
  // A blank expectedUnits is "not provided", not EMPTY.
  const blankExpected = run({ ...base, expectedUnits: "" });
  assert.equal(blankExpected.ok, true);
  assert.equal(blankExpected.result.marginOfSafety, null);
});

test("the first field in the fixed order reports first, and a field error wins over NO_MARGIN", () => {
  assert.deepEqual(errorOf({ ...base, fixedCost: "bad", price: "bad" }), {
    code: "DECIMAL_FORMAT",
    field: "fixedCost",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, price: "bad", variableCost: "bad" }), {
    code: "DECIMAL_FORMAT",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, variableCost: "bad", expectedUnits: "1.5" }), {
    code: "DECIMAL_FORMAT",
    field: "variableCost",
    row: null,
  });
  // price 0 with variableCost above it is RANGE, not NO_MARGIN.
  assert.deepEqual(errorOf({ ...base, price: "0", variableCost: "200" }), {
    code: "RANGE",
    field: "price",
    row: null,
  });
  // A grammar error in an earlier field wins over NO_MARGIN too.
  assert.deepEqual(errorOf({ ...base, fixedCost: "1.234", price: "150", variableCost: "200" }), {
    code: "DECIMAL_FORMAT",
    field: "fixedCost",
    row: null,
  });
});

test("expected units grammar: decimals, signs and commas are INTEGER_FORMAT", () => {
  for (const bad of ["10.5", "-5", "+5", "1,000", "1e3", " 10"]) {
    assert.deepEqual(errorOf({ ...base, expectedUnits: bad }), {
      code: "INTEGER_FORMAT",
      field: "expectedUnits",
      row: null,
    });
  }
  // Leading zeros are not accepted by the integer grammar either.
  assert.deepEqual(errorOf({ ...base, expectedUnits: "007" }), {
    code: "INTEGER_FORMAT",
    field: "expectedUnits",
    row: null,
  });
});

test("F = 0 with E = 0: percent is null, belowBreakeven is false, profit is 0.00 (no negative zero)", () => {
  const outcome = run({ fixedCost: "0", price: "400", variableCost: "150", expectedUnits: "0" });
  assert.equal(outcome.ok, true);
  assert.deepEqual(outcome.result.marginOfSafety, {
    expectedUnits: 0,
    units: 0,
    percent: null,
    expectedProfit: "0.00",
    belowBreakeven: false,
  });
});

test("negative half-up tie: a -0.005% margin of safety rounds toward +infinity to 0.00", () => {
  // M = 1 cent, F = 20001 cents, so U = 20001; E = 20000 gives
  // percent = (20000 - 20001) * 100 / 20000 = -0.005 exactly, a tie.
  // R(-0.005, 2) = floor(-0.5 + 0.5) / 100 = 0.00, not -0.01.
  const outcome = run({
    fixedCost: "200.01",
    price: "100",
    variableCost: "99.99",
    expectedUnits: "20000",
  });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.breakevenUnits, 20001);
  assert.equal(outcome.result.marginOfSafety.percent, "0.00");
  assert.equal(outcome.result.marginOfSafety.units, -1);
  assert.equal(outcome.result.marginOfSafety.expectedProfit, "-0.01");
  assert.equal(outcome.result.marginOfSafety.belowBreakeven, true);
});

test("property: every success fixture satisfies the ceil invariant and the revenue gap bound", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    const { fixedCost, price, variableCost } = entry.input;
    const F = moneyToCents(fixedCost);
    const P = moneyToCents(price);
    const M = P - moneyToCents(variableCost);
    const U = BigInt(entry.expected.result.breakevenUnits);
    if (U >= 1n) {
      assert.ok((U - 1n) * M < F, `${entry.id}: (U-1)*M < F`);
      assert.ok(F <= U * M, `${entry.id}: F <= U*M`);
    }
    // Unrounded theoretical revenue F*P/M <= whole-unit revenue U*P,
    // with the gap strictly less than one unit price P.
    const wholeRevenueCents = U * P;
    assert.ok(F * P <= wholeRevenueCents * M, `${entry.id}: theoretical revenue <= whole revenue`);
    assert.ok(wholeRevenueCents * M - F * P < P * M, `${entry.id}: revenue gap < one unit price`);
  }
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.price;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, fixedCost: 120000 }), schema);
  assert.deepEqual(errorOf({ ...base, expectedUnits: null }), schema);
  assert.deepEqual(errorOf(["120000"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("120000"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "price", {
    enumerable: true,
    get() {
      return "400";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...base, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...base };
  stringObject.price = new String("400");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("the core does not mutate its input", () => {
  const input = { ...base, expectedUnits: "800" };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...base, price: "0" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("formatting: money and fixed-decimal strings, including negatives and zero", () => {
  assert.equal(formatMoney(0n), "0.00");
  assert.equal(formatMoney(1n), "0.01");
  assert.equal(formatMoney(-1n), "-0.01");
  assert.equal(formatMoney(-2000000n), "-20000.00");
  assert.equal(formatMoney(19752960n), "197529.60");
  assert.equal(formatFixedScaled(0n, 2), "0.00");
  assert.equal(formatFixedScaled(-5n, 2), "-0.05");
  assert.equal(formatFixedScaled(268n, 2), "2.68");
  assert.equal(formatFixedScaled(4938240n, 4), "493.8240");
});
